"""Generated by the NL to Flow Diagram Encoder Pipeline."""

arr = [1, 3, (-1), (-3), 5, 3, 6, 7]

k = 2

results = []

start = 0

loop = True

while loop:
    end = (start + k)
    if (end > len(arr)):
        break
    index = start
    innerloop = True
    maxval = arr[start]
    while innerloop:
        try:
            if (arr[index] > maxval):
                maxval = arr[index]
            index = (index + 1)
        except Exception:
            innerloop = False
        if (index >= end):
            innerloop = False
    results.append(maxval)
    start = (start + 1)

print(f'Sliding Window Maximums From Window Size {k}:')

print(results)
